sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue == '') {
        return;
    }

    var category = g_form.getValue('category');

    if (category == 'cash' && newValue == 'covid_vaccination') {
        g_form.setSectionDisplay('covid_vaccination', true);
        //(g_form.getSectionNames());
        g_form.setMandatory('dose', true);
        g_form.setMandatory('bill_no', true);
        g_form.setMandatory('date', true);
        g_form.setMandatory('amount', true);
        g_form.setMandatory('total_amount', true);
    } else {
        g_form.setSectionDisplay('covid_vaccination', false);
        g_form.setMandatory('dose', false);
        g_form.setMandatory('bill_no', false);
        g_form.setMandatory('date', false);
        g_form.setMandatory('amount', false);
        g_form.setMandatory('total_amount', false);
    }
}
